KIND = "atlas"
SYSTEM = "articular"
E = {
"art-sacroiliaca": {
"en": ["Sacroiliac joint", "The joint between the ear-shaped (auricular) surfaces of the sacrum and the hip bone, held by very strong ligaments. It transfers the weight of the trunk to the lower limbs.",
 ["Synovial in front, syndesmosis behind (mixed joint); very little movement",
  "Anterior, interosseous (strongest) and posterior sacroiliac ligaments; accessory ligaments: sacrotuberous, sacrospinous, iliolumbar",
  "Very limited gliding and rotation (nutation–counternutation); loosens under hormonal influence in pregnancy"], [],
 ["Sacroiliitis is an early sign of seronegative spondyloarthropathies such as ankylosing spondylitis.", "It is an often overlooked cause of low back and hip pain."],
 ["The front of the sacroiliac joint is synovial, the back a syndesmosis.", "Sacroiliitis is an early, characteristic finding of ankylosing spondylitis."], ["SI joint"]],
"fr": ["Articulation sacro-iliaque", "Articulation entre les surfaces auriculaires du sacrum et de l'os coxal, maintenue par des ligaments très puissants. Elle transmet le poids du tronc aux membres inférieurs.",
 ["Synoviale en avant, syndesmose en arrière (articulation mixte) ; très peu mobile",
  "Ligaments sacro-iliaques antérieur, interosseux (le plus solide) et postérieur ; ligaments accessoires : sacro-tubéral, sacro-épineux, ilio-lombaire",
  "Glissements et rotations très limités (nutation–contre-nutation) ; se relâche sous l'effet hormonal pendant la grossesse"], [],
 ["La sacro-iliite est un signe précoce des spondylarthropathies séronégatives comme la spondylarthrite ankylosante.", "C'est une cause souvent méconnue de lombalgie et de douleur de hanche."],
 ["La partie antérieure de l'articulation sacro-iliaque est synoviale, la partie postérieure une syndesmose.", "La sacro-iliite est un signe précoce et caractéristique de la spondylarthrite ankylosante."], ["SI"]],
"de": ["Iliosakralgelenk", "Gelenk zwischen den ohrförmigen Flächen (Facies auriculares) von Kreuzbein und Hüftbein, gesichert durch sehr kräftige Bänder. Es überträgt das Rumpfgewicht auf die Beine.",
 ["Vorn synovial, hinten Syndesmose (Mischgelenk); kaum beweglich",
  "Lig. sacroiliacum anterius, interosseum (das stärkste) und posterius; Hilfsbänder: Lig. sacrotuberale, sacrospinale, iliolumbale",
  "Sehr geringe Gleit- und Drehbewegung (Nutation–Kontranutation); lockert sich in der Schwangerschaft hormonell"], [],
 ["Die Sakroiliitis ist ein Frühzeichen seronegativer Spondyloarthritiden wie des Morbus Bechterew.", "Sie ist eine oft übersehene Ursache von Kreuz- und Hüftschmerzen."],
 ["Der vordere Teil des Iliosakralgelenks ist synovial, der hintere eine Syndesmose.", "Die Sakroiliitis ist ein frühes, typisches Zeichen des Morbus Bechterew."], ["ISG", "Iliosakral"]],
"es": ["Articulación sacroilíaca", "Articulación entre las carillas auriculares del sacro y del coxal, sujeta por ligamentos muy potentes. Transmite el peso del tronco a los miembros inferiores.",
 ["Sinovial por delante, sindesmosis por detrás (articulación mixta); muy poco móvil",
  "Ligamentos sacroilíacos anterior, interóseo (el más fuerte) y posterior; ligamentos accesorios: sacrotuberoso, sacroespinoso, iliolumbar",
  "Deslizamiento y rotación muy limitados (nutación–contranutación); se relaja por efecto hormonal en el embarazo"], [],
 ["La sacroileítis es un signo precoz de las espondiloartropatías seronegativas como la espondilitis anquilosante.", "Es una causa a menudo olvidada de dolor lumbar y de cadera."],
 ["La parte anterior de la sacroilíaca es sinovial y la posterior una sindesmosis.", "La sacroileítis es un hallazgo precoz y característico de la espondilitis anquilosante."], ["sacroilíaca"]],
},
"symphysis-pubica": {
"en": ["Pubic symphysis", "The joint where the two pubic bones meet in the midline, joined by a fibrocartilaginous disc (interpubic disc).",
 ["Symphysis (secondary cartilaginous joint)", "Superior pubic ligament, inferior (arcuate) pubic ligament", "Very limited; widens slightly during childbirth"], [],
 ["Separation of the symphysis (diastasis) in pregnancy can make walking painful.", "Osteitis pubis causes groin pain in athletes."],
 ["In pregnancy the symphysis can widen by a few millimetres under the influence of relaxin.", "The upper border of the symphysis is the front boundary of the pelvic inlet; the empty bladder lies behind it."], ["symphysis"]],
"fr": ["Symphyse pubienne", "Articulation par laquelle les deux os pubis s'unissent sur la ligne médiane, par l'intermédiaire d'un disque fibrocartilagineux (disque interpubien).",
 ["Symphyse (articulation cartilagineuse secondaire)", "Ligament pubien supérieur, ligament pubien inférieur (arqué)", "Très limité ; s'écarte légèrement lors de l'accouchement"], [],
 ["La disjonction de la symphyse pendant la grossesse peut rendre la marche douloureuse.", "L'ostéite pubienne provoque des douleurs inguinales chez le sportif."],
 ["Pendant la grossesse, la symphyse peut s'écarter de quelques millimètres sous l'effet de la relaxine.", "Le bord supérieur de la symphyse est la limite antérieure du détroit supérieur ; la vessie vide se trouve en arrière."], []],
"de": ["Schambeinfuge", "Die Verbindung der beiden Schambeine in der Mittellinie über eine Faserknorpelscheibe (Discus interpubicus).",
 ["Symphyse (sekundär knorpeliges Gelenk)", "Lig. pubicum superius, Lig. pubicum inferius (arcuatum)", "Sehr gering; weitet sich bei der Geburt etwas"], [],
 ["Eine Symphysenlockerung (Diastase) in der Schwangerschaft kann das Gehen schmerzhaft machen.", "Die Osteitis pubis verursacht bei Sportlern Leistenschmerzen."],
 ["In der Schwangerschaft kann sich die Symphyse unter Relaxin um einige Millimeter erweitern.", "Der Oberrand der Symphyse ist die vordere Grenze des Beckeneingangs; die leere Blase liegt dahinter."], ["Symphyse", "Symphysis pubica"]],
"es": ["Sínfisis del pubis", "Articulación en la que los dos pubis se unen en la línea media mediante un disco fibrocartilaginoso (disco interpúbico).",
 ["Sínfisis (articulación cartilaginosa secundaria)", "Ligamento púbico superior, ligamento púbico inferior (arqueado)", "Muy limitado; se ensancha ligeramente en el parto"], [],
 ["La separación de la sínfisis (diástasis) en el embarazo puede hacer doloroso caminar.", "La osteítis del pubis causa dolor inguinal en deportistas."],
 ["En el embarazo la sínfisis puede ensancharse unos milímetros por efecto de la relaxina.", "El borde superior de la sínfisis es el límite anterior del estrecho superior; la vejiga vacía está detrás."], ["sínfisis"]],
},
"ligg-pelvis": {
"en": ["Ligaments of the pelvis", "Strong ligaments between the sacrum and the hip bone that turn the sciatic notches into foramina, and the membrane that closes the obturator foramen.",
 ["From the edge of the sacrum and coccyx to the ischial tuberosity", "From the edge of the sacrum and coccyx to the ischial spine",
  "Greater sciatic foramen (piriformis, gluteal vessels and nerves, sciatic nerve) and lesser sciatic foramen (obturator internus tendon, pudendal nerve)",
  "Closes the obturator foramen, leaving the obturator canal above", "From the L5 transverse process to the iliac crest"], [],
 ["A pudendal nerve block (in labour) is given just beside the ischial spine, around the sacrospinous ligament."],
 ["The sacrospinous and sacrotuberous ligaments stop the sacrum tipping forwards (nutation).", "The iliolumbar ligament binds the L5 transverse process to the iliac crest and limits forward slip of L5."], []],
"fr": ["Ligaments du bassin", "Ligaments puissants tendus entre le sacrum et l'os coxal, qui transforment les incisures ischiatiques en foramens, et membrane qui ferme le foramen obturé.",
 ["Du bord du sacrum et du coccyx à la tubérosité ischiatique", "Du bord du sacrum et du coccyx à l'épine ischiatique",
  "Grand foramen ischiatique (piriforme, vaisseaux et nerfs glutéaux, nerf sciatique) et petit foramen ischiatique (tendon de l'obturateur interne, nerf pudendal)",
  "Ferme le foramen obturé en laissant en haut le canal obturateur", "Du processus transverse de L5 à la crête iliaque"], [],
 ["Le bloc du nerf pudendal (lors de l'accouchement) se fait juste à côté de l'épine ischiatique, autour du ligament sacro-épineux."],
 ["Les ligaments sacro-épineux et sacro-tubéral empêchent la bascule antérieure du sacrum (nutation).", "Le ligament ilio-lombaire unit le processus transverse de L5 à la crête iliaque et limite le glissement antérieur de L5."], []],
"de": ["Bänder des Beckens", "Kräftige Bänder zwischen Kreuzbein und Hüftbein, die die Incisurae ischiadicae zu Foramina schließen, sowie die Membran, die das Foramen obturatum verschließt.",
 ["Vom Rand von Kreuz- und Steißbein zum Tuber ischiadicum", "Vom Rand von Kreuz- und Steißbein zur Spina ischiadica",
  "Foramen ischiadicum majus (M. piriformis, Glutealgefäße und -nerven, N. ischiadicus) und minus (Sehne des M. obturatorius internus, N. pudendus)",
  "Verschließt das Foramen obturatum und lässt oben den Canalis obturatorius frei", "Vom Querfortsatz L5 zum Beckenkamm"], [],
 ["Die Pudendusblockade (unter der Geburt) erfolgt direkt neben der Spina ischiadica im Bereich des Lig. sacrospinale."],
 ["Lig. sacrospinale und sacrotuberale verhindern das Vorkippen des Kreuzbeins (Nutation).", "Das Lig. iliolumbale verbindet den Querfortsatz L5 mit dem Beckenkamm und begrenzt das Vorgleiten von L5."], []],
"es": ["Ligamentos de la pelvis", "Ligamentos potentes entre el sacro y el coxal que convierten las escotaduras isquiáticas en agujeros, y la membrana que cierra el agujero obturador.",
 ["Del borde del sacro y el cóccix a la tuberosidad isquiática", "Del borde del sacro y el cóccix a la espina isquiática",
  "Agujero isquiático mayor (piriforme, vasos y nervios glúteos, nervio ciático) y menor (tendón del obturador interno, nervio pudendo)",
  "Cierra el agujero obturador y deja arriba el conducto obturador", "De la apófisis transversa de L5 a la cresta ilíaca"], [],
 ["El bloqueo del nervio pudendo (en el parto) se realiza junto a la espina isquiática, alrededor del ligamento sacroespinoso."],
 ["Los ligamentos sacroespinoso y sacrotuberoso impiden la inclinación anterior del sacro (nutación).", "El ligamento iliolumbar une la apófisis transversa de L5 a la cresta ilíaca y limita el deslizamiento anterior de L5."], []],
},
"art-coxae": {
"en": ["Hip joint", "The ball-and-socket joint between the head of the femur and the acetabulum of the hip bone. Thanks to its deep socket and strong ligaments it is far more stable than the shoulder.",
 ["Synovial ball-and-socket joint (spheroidal; enarthrosis)", "Head of femur – lunate surface of the acetabulum; the acetabular labrum and transverse acetabular ligament deepen the socket",
  "Iliofemoral ligament (Y ligament – the strongest ligament in the body, prevents hyperextension), pubofemoral ligament, ischiofemoral ligament, ligament of the head of the femur, zona orbicularis",
  "Flexion (~120°), extension (~20°), abduction, adduction, internal and external rotation",
  "Medial (main) and lateral circumflex femoral arteries, obturator artery (artery of the ligament of the head)",
  "Branches of the femoral, obturator and sciatic nerves – hip pain may be referred to the knee"], [],
 ["Developmental dysplasia of the hip is screened in newborns with the Ortolani and Barlow manoeuvres.",
  "Posterior hip dislocation (e.g. knee striking the dashboard) can injure the sciatic nerve; the leg is short, flexed, adducted and internally rotated.",
  "Advanced hip osteoarthritis needs a total hip replacement; hip pain may be felt in the groin and knee."],
 ["The hip is most stable in extension, abduction and internal rotation (ligaments taut).", "Developmental dysplasia of the hip is screened in newborns with the Ortolani and Barlow manoeuvres."], ["hip"]],
"fr": ["Articulation de la hanche", "Articulation sphéroïde entre la tête fémorale et l'acétabulum de l'os coxal. Grâce à son cotyle profond et à ses ligaments puissants, elle est bien plus stable que l'épaule.",
 ["Articulation synoviale sphéroïde (énarthrose)", "Tête fémorale – surface semi-lunaire de l'acétabulum ; le labrum acétabulaire et le ligament transverse de l'acétabulum approfondissent le cotyle",
  "Ligament ilio-fémoral (ligament en Y – le plus puissant du corps, empêche l'hyperextension), ligament pubo-fémoral, ligament ischio-fémoral, ligament de la tête fémorale, zone orbiculaire",
  "Flexion (~120°), extension (~20°), abduction, adduction, rotations médiale et latérale",
  "Artères circonflexes médiale (principale) et latérale de la cuisse, artère obturatrice (artère du ligament de la tête)",
  "Branches des nerfs fémoral, obturateur et sciatique – la douleur de hanche peut irradier au genou"], [],
 ["La dysplasie développementale de la hanche est dépistée chez le nouveau-né par les manœuvres d'Ortolani et de Barlow.",
  "La luxation postérieure de hanche (p. ex. genou heurtant le tableau de bord) peut léser le nerf sciatique ; le membre est raccourci, en flexion, adduction et rotation médiale.",
  "La coxarthrose évoluée nécessite une prothèse totale de hanche ; la douleur peut être ressentie dans l'aine et le genou."],
 ["La hanche est la plus stable en extension, abduction et rotation médiale (ligaments tendus).", "La dysplasie de hanche est dépistée chez le nouveau-né par les manœuvres d'Ortolani et de Barlow."], ["hanche", "coxo-fémorale"]],
"de": ["Hüftgelenk", "Kugelgelenk zwischen Femurkopf und Hüftpfanne (Acetabulum). Dank der tiefen Pfanne und der kräftigen Bänder ist es weit stabiler als das Schultergelenk.",
 ["Synoviales Kugelgelenk (Nussgelenk, Enarthrose)", "Caput femoris – Facies lunata acetabuli; Labrum acetabuli und Lig. transversum acetabuli vertiefen die Pfanne",
  "Lig. iliofemorale (Y-Band – stärkstes Band des Körpers, verhindert Überstreckung), Lig. pubofemorale, Lig. ischiofemorale, Lig. capitis femoris, Zona orbicularis",
  "Flexion (~120°), Extension (~20°), Abduktion, Adduktion, Innen- und Außenrotation",
  "A. circumflexa femoris medialis (hauptsächlich) und lateralis, A. obturatoria (Arterie des Lig. capitis femoris)",
  "Äste von N. femoralis, N. obturatorius und N. ischiadicus – Hüftschmerz kann ins Knie ausstrahlen"], [],
 ["Die Hüftdysplasie wird beim Neugeborenen mit den Ortolani- und Barlow-Manövern gesucht.",
  "Die hintere Hüftluxation (z. B. Knie gegen das Armaturenbrett) kann den N. ischiadicus schädigen; das Bein ist verkürzt, gebeugt, adduziert und innenrotiert.",
  "Fortgeschrittene Koxarthrose erfordert eine Hüfttotalendoprothese; der Schmerz kann in Leiste und Knie empfunden werden."],
 ["Das Hüftgelenk ist in Extension, Abduktion und Innenrotation am stabilsten (Bänder gespannt).", "Die Hüftdysplasie wird beim Neugeborenen mit Ortolani- und Barlow-Test gesucht."], ["Hüfte"]],
"es": ["Articulación de la cadera", "Articulación esferoidea entre la cabeza del fémur y el acetábulo del coxal. Gracias a su cavidad profunda y sus fuertes ligamentos es mucho más estable que el hombro.",
 ["Articulación sinovial esferoidea (enartrosis)", "Cabeza del fémur – carilla semilunar del acetábulo; el labrum acetabular y el ligamento transverso del acetábulo profundizan la cavidad",
  "Ligamento iliofemoral (ligamento en Y – el más fuerte del cuerpo, impide la hiperextensión), ligamento pubofemoral, ligamento isquiofemoral, ligamento de la cabeza del fémur, zona orbicular",
  "Flexión (~120°), extensión (~20°), abducción, aducción, rotación interna y externa",
  "Arterias circunflejas femorales medial (principal) y lateral, arteria obturatriz (arteria del ligamento de la cabeza)",
  "Ramas de los nervios femoral, obturador y ciático – el dolor de cadera puede referirse a la rodilla"], [],
 ["La displasia del desarrollo de la cadera se cribe en el recién nacido con las maniobras de Ortolani y Barlow.",
  "La luxación posterior de cadera (p. ej. rodilla contra el salpicadero) puede lesionar el nervio ciático; la pierna queda corta, en flexión, aducción y rotación interna.",
  "La coxartrosis avanzada requiere una prótesis total de cadera; el dolor puede notarse en la ingle y la rodilla."],
 ["La cadera es más estable en extensión, abducción y rotación interna (ligamentos tensos).", "La displasia de cadera se cribe en el recién nacido con las maniobras de Ortolani y Barlow."], ["cadera"]],
},
"art-genus": {
"en": ["Knee joint", "The largest and most complex joint in the body. It consists of the joints between the femoral and tibial condyles (tibiofemoral) and between the patella and femur (patellofemoral); its stability depends largely on ligaments and muscles.",
 ["Synovial bicondylar (modified hinge) joint",
  "Medial meniscus (C-shaped, attached to the medial collateral ligament) and lateral meniscus (O-shaped, more mobile); anterior and posterior cruciate ligaments; infrapatellar fat pad (Hoffa's fat pad)",
  "Tibial (medial) collateral ligament, fibular (lateral) collateral ligament, patellar ligament, oblique and arcuate popliteal ligaments",
  "Flexion (~140°), extension; limited rotation when the knee is bent; locking in full extension as the femur rotates medially (screw-home mechanism)",
  "Suprapatellar bursa (communicates with the joint cavity), prepatellar, infrapatellar, anserine bursae"],
 [["Cruciate ligaments", "The anterior cruciate ligament (ACL) stops the tibia sliding forwards on the femur, the posterior cruciate ligament (PCL) stops it sliding backwards. They are named after their tibial attachments."]],
 ["'Unhappy triad' (O'Donoghue): combined injury of the medial collateral ligament, ACL and medial meniscus from a blow to the outer side of the knee.",
  "In an ACL tear the anterior drawer and Lachman tests are positive.", "Meniscal tears cause joint-line tenderness, locking and a positive McMurray test.", "A Baker's (popliteal) cyst behind the knee is common."],
 ["The knee has three compartments: medial and lateral femorotibial and patellofemoral.", "The suprapatellar bursa communicates with the joint cavity; a knee effusion is felt here (patellar tap)."], ["knee"]],
"fr": ["Articulation du genou", "La plus grande et la plus complexe des articulations du corps. Elle comprend les articulations entre condyles fémoraux et tibiaux (fémoro-tibiale) et entre patella et fémur (fémoro-patellaire) ; sa stabilité repose surtout sur les ligaments et les muscles.",
 ["Articulation synoviale bicondylaire (trochléenne modifiée)",
  "Ménisque médial (en C, adhérent au ligament collatéral tibial) et ménisque latéral (en O, plus mobile) ; ligaments croisés antérieur et postérieur ; corps adipeux infrapatellaire (de Hoffa)",
  "Ligament collatéral tibial (médial), ligament collatéral fibulaire (latéral), ligament patellaire, ligaments poplités oblique et arqué",
  "Flexion (~140°), extension ; rotation limitée genou fléchi ; verrouillage en extension complète par rotation médiale du fémur (screw-home)",
  "Bourse suprapatellaire (communiquant avec la cavité articulaire), bourses prépatellaire, infrapatellaire, ansérine"],
 [["Ligaments croisés", "Le ligament croisé antérieur (LCA) empêche le tibia de glisser en avant sous le fémur, le ligament croisé postérieur (LCP) l'empêche de glisser en arrière. Ils sont nommés d'après leur insertion tibiale."]],
 ["Triade malheureuse (O'Donoghue) : lésion associée du ligament collatéral médial, du LCA et du ménisque médial après un choc sur la face latérale du genou.",
  "En cas de rupture du LCA, les tests du tiroir antérieur et de Lachman sont positifs.", "Les lésions méniscales donnent une douleur de l'interligne, des blocages et un test de McMurray positif.", "Le kyste poplité (de Baker) est fréquent à la face postérieure du genou."],
 ["Le genou comporte trois compartiments : fémoro-tibiaux médial et latéral, fémoro-patellaire.", "La bourse suprapatellaire communique avec la cavité articulaire ; c'est là que l'on perçoit l'épanchement (choc patellaire)."], ["genou"]],
"de": ["Kniegelenk", "Das größte und komplexeste Gelenk des Körpers. Es besteht aus dem Gelenk zwischen Femur- und Tibiakondylen (femorotibial) und dem zwischen Patella und Femur (femoropatellar); seine Stabilität beruht vor allem auf Bändern und Muskeln.",
 ["Synoviales bikondyläres Gelenk (Dreh-Scharnier-Gelenk)",
  "Innenmeniskus (C-förmig, mit dem Innenband verwachsen) und Außenmeniskus (O-förmig, beweglicher); vorderes und hinteres Kreuzband; Corpus adiposum infrapatellare (Hoffa-Fettkörper)",
  "Lig. collaterale tibiale (Innenband), Lig. collaterale fibulare (Außenband), Lig. patellae, Lig. popliteum obliquum und arcuatum",
  "Flexion (~140°), Extension; bei gebeugtem Knie begrenzte Rotation; Schlussrotation in voller Streckung durch Innenrotation des Femurs (Screw-home)",
  "Bursa suprapatellaris (mit der Gelenkhöhle verbunden), Bursa praepatellaris, infrapatellaris, anserina"],
 [["Kreuzbänder", "Das vordere Kreuzband (VKB) verhindert das Vorgleiten der Tibia gegenüber dem Femur, das hintere (HKB) das Zurückgleiten. Benannt sind sie nach ihrem tibialen Ansatz."]],
 ["„Unhappy Triad“ (O'Donoghue): kombinierte Verletzung von Innenband, VKB und Innenmeniskus durch einen Stoß gegen die Knieaußenseite.",
  "Beim VKB-Riss sind vordere Schublade und Lachman-Test positiv.", "Meniskusrisse verursachen Gelenkspaltschmerz, Einklemmungen und einen positiven McMurray-Test.", "Eine Baker-Zyste (Poplitealzyste) in der Kniekehle ist häufig."],
 ["Das Knie hat drei Kompartimente: mediales und laterales femorotibiales sowie femoropatellares.", "Die Bursa suprapatellaris steht mit der Gelenkhöhle in Verbindung; dort tastet man den Erguss (tanzende Patella)."], ["Knie"]],
"es": ["Articulación de la rodilla", "La articulación más grande y compleja del cuerpo. Comprende las articulaciones entre los cóndilos femorales y tibiales (femorotibial) y entre la rótula y el fémur (femororrotuliana); su estabilidad depende sobre todo de ligamentos y músculos.",
 ["Articulación sinovial bicondílea (bisagra modificada)",
  "Menisco medial (en C, unido al ligamento colateral tibial) y menisco lateral (en O, más móvil); ligamentos cruzados anterior y posterior; cuerpo adiposo infrarrotuliano (grasa de Hoffa)",
  "Ligamento colateral tibial (medial), ligamento colateral peroneo (lateral), ligamento rotuliano, ligamentos poplíteos oblicuo y arqueado",
  "Flexión (~140°), extensión; rotación limitada con la rodilla flexionada; bloqueo en extensión completa por rotación interna del fémur (mecanismo de atornillamiento)",
  "Bolsa suprarrotuliana (comunica con la cavidad articular), bolsas prerrotuliana, infrarrotuliana, anserina"],
 [["Ligamentos cruzados", "El ligamento cruzado anterior (LCA) impide que la tibia se deslice hacia delante respecto al fémur; el posterior (LCP), que se deslice hacia atrás. Se nombran por su inserción tibial."]],
 ["«Tríada desgraciada» (O'Donoghue): lesión combinada del ligamento colateral medial, el LCA y el menisco medial por un golpe en la cara lateral de la rodilla.",
  "En la rotura del LCA el cajón anterior y el test de Lachman son positivos.", "Las roturas meniscales causan dolor en la interlínea, bloqueos y test de McMurray positivo.", "El quiste de Baker (poplíteo) detrás de la rodilla es frecuente."],
 ["La rodilla tiene tres compartimentos: femorotibiales medial y lateral y femororrotuliano.", "La bolsa suprarrotuliana comunica con la cavidad articular; ahí se palpa el derrame (choque rotuliano)."], ["rodilla"]],
},
"meniscus": {
"en": ["Menisci of the knee", "Two fibrocartilaginous rings, triangular in section, between the femoral and tibial condyles. They improve the fit of the articular surfaces and spread the load.",
 ["C-shaped and wide; attached to the tibial collateral ligament, so less mobile and more often torn", "Roughly O-shaped, smaller and more mobile; connected to popliteus",
  "Meniscotibial ligaments, transverse ligament of the knee, meniscofemoral ligaments", "Only the outer third (red zone) is vascularised; the inner part heals poorly"], [],
 ["A sudden twist of the bent, weight-bearing knee tears a meniscus; a bucket-handle tear can lock the knee."],
 ["The outer third of the menisci is vascularised (red zone) and can be repaired; the inner two thirds are avascular.", "Bucket-handle tears cause locking of the joint."], ["meniscus"]],
"fr": ["Ménisques du genou", "Deux anneaux fibrocartilagineux, triangulaires en coupe, situés entre les condyles fémoraux et tibiaux. Ils améliorent la congruence des surfaces articulaires et répartissent les charges.",
 ["En C, large ; adhérent au ligament collatéral tibial, donc moins mobile et plus souvent lésé", "Presque en O, plus petit et plus mobile ; relié au muscle poplité",
  "Ligaments ménisco-tibiaux, ligament transverse du genou, ligaments ménisco-fémoraux", "Seul le tiers périphérique (zone rouge) est vascularisé ; la partie interne cicatrise mal"], [],
 ["Une torsion brutale du genou fléchi en charge déchire un ménisque ; une lésion en anse de seau peut bloquer le genou."],
 ["Le tiers périphérique des ménisques est vascularisé (zone rouge) et suturable ; les deux tiers internes sont avasculaires.", "Les lésions en anse de seau entraînent un blocage articulaire."], ["ménisque"]],
"de": ["Menisken", "Zwei im Querschnitt dreieckige Faserknorpelringe zwischen Femur- und Tibiakondylen. Sie verbessern die Passung der Gelenkflächen und verteilen die Last.",
 ["C-förmig und breit; mit dem Innenband verwachsen, daher weniger beweglich und häufiger gerissen", "Annähernd O-förmig, kleiner und beweglicher; mit dem M. popliteus verbunden",
  "Ligg. meniscotibialia, Lig. transversum genus, Ligg. meniscofemoralia", "Nur das äußere Drittel (rote Zone) ist durchblutet; der innere Teil heilt schlecht"], [],
 ["Eine plötzliche Drehung des gebeugten, belasteten Knies reißt einen Meniskus; ein Korbhenkelriss kann das Knie blockieren."],
 ["Das äußere Drittel der Menisken ist durchblutet (rote Zone) und nahtfähig; die inneren zwei Drittel sind gefäßlos.", "Korbhenkelrisse führen zur Gelenkblockade."], ["Meniskus"]],
"es": ["Meniscos de la rodilla", "Dos anillos de fibrocartílago, triangulares en sección, entre los cóndilos femorales y tibiales. Mejoran el ajuste de las superficies articulares y reparten la carga.",
 ["En forma de C y ancho; unido al ligamento colateral tibial, por eso es menos móvil y se rompe más", "Casi en forma de O, más pequeño y móvil; unido al poplíteo",
  "Ligamentos meniscotibiales, ligamento transverso de la rodilla, ligamentos meniscofemorales", "Solo el tercio externo (zona roja) está irrigado; la parte interna cicatriza mal"], [],
 ["Un giro brusco de la rodilla flexionada y en carga rompe el menisco; una rotura en asa de cubo puede bloquear la rodilla."],
 ["El tercio externo de los meniscos está irrigado (zona roja) y puede suturarse; los dos tercios internos son avasculares.", "Las roturas en asa de cubo producen bloqueo articular."], ["menisco"]],
},
"ligg-cruciata": {
"en": ["Cruciate ligaments", "Two strong ligaments that cross each other inside the knee joint (but outside the synovial membrane): the anterior cruciate ligament (ACL) and the posterior cruciate ligament (PCL).",
 ["From the anterior intercondylar area of the tibia to the inner surface of the lateral femoral condyle; prevents forward slide of the tibia and hyperextension",
  "From the posterior intercondylar area of the tibia to the outer surface of the medial femoral condyle; prevents backward slide of the tibia; the stronger of the two",
  "Middle genicular artery (popliteal artery)"], [],
 ["ACL tears occur in athletes during sudden changes of direction and landings; a 'pop' and rapid swelling (haemarthrosis) are typical.",
  "PCL tears occur in dashboard injuries (bent knee striking the dashboard); the posterior drawer test is positive."],
 ["The ACL runs from the anterior intercondylar area of the tibia to the inner surface of the lateral femoral condyle, the PCL from the posterior intercondylar area to the outer surface of the medial condyle.",
  "The cruciate ligaments lie inside the joint capsule but outside the synovial membrane (intracapsular, extrasynovial)."], ["ACL", "PCL"]],
"fr": ["Ligaments croisés", "Deux ligaments puissants qui se croisent dans l'articulation du genou (mais hors de la synoviale) : le ligament croisé antérieur (LCA) et le ligament croisé postérieur (LCP).",
 ["De l'aire intercondylaire antérieure du tibia à la face interne du condyle fémoral latéral ; empêche le glissement antérieur du tibia et l'hyperextension",
  "De l'aire intercondylaire postérieure du tibia à la face externe du condyle fémoral médial ; empêche le glissement postérieur du tibia ; le plus puissant",
  "Artère moyenne du genou (artère poplitée)"], [],
 ["La rupture du LCA survient chez le sportif lors des changements de direction et des réceptions ; un « pop » et un gonflement rapide (hémarthrose) sont typiques.",
  "La rupture du LCP survient dans le syndrome du tableau de bord (genou fléchi heurtant le tableau de bord) ; le tiroir postérieur est positif."],
 ["Le LCA va de l'aire intercondylaire antérieure du tibia à la face interne du condyle latéral, le LCP de l'aire intercondylaire postérieure à la face externe du condyle médial.",
  "Les ligaments croisés sont intracapsulaires mais extrasynoviaux."], ["LCA", "LCP"]],
"de": ["Kreuzbänder", "Zwei kräftige Bänder, die sich im Kniegelenk (aber außerhalb der Synovialmembran) kreuzen: das vordere Kreuzband (VKB) und das hintere Kreuzband (HKB).",
 ["Von der Area intercondylaris anterior der Tibia zur Innenfläche des lateralen Femurkondylus; verhindert das Vorgleiten der Tibia und die Überstreckung",
  "Von der Area intercondylaris posterior der Tibia zur Außenfläche des medialen Femurkondylus; verhindert das Zurückgleiten der Tibia; das stärkere der beiden",
  "A. media genus (A. poplitea)"], [],
 ["VKB-Risse entstehen bei Sportlern durch plötzliche Richtungswechsel und Landungen; typisch sind ein „Plopp“ und rasche Schwellung (Hämarthros).",
  "HKB-Risse entstehen bei Armaturenbrettverletzungen (gebeugtes Knie prallt aufs Armaturenbrett); die hintere Schublade ist positiv."],
 ["Das VKB zieht von der Area intercondylaris anterior der Tibia zur Innenfläche des lateralen Kondylus, das HKB von der Area intercondylaris posterior zur Außenfläche des medialen Kondylus.",
  "Die Kreuzbänder liegen intrakapsulär, aber extrasynovial."], ["VKB", "HKB", "Kreuzband"]],
"es": ["Ligamentos cruzados", "Dos ligamentos potentes que se cruzan dentro de la rodilla (pero fuera de la membrana sinovial): el ligamento cruzado anterior (LCA) y el posterior (LCP).",
 ["Del área intercondílea anterior de la tibia a la cara interna del cóndilo femoral lateral; impide el deslizamiento anterior de la tibia y la hiperextensión",
  "Del área intercondílea posterior de la tibia a la cara externa del cóndilo femoral medial; impide el deslizamiento posterior de la tibia; es el más fuerte",
  "Arteria genicular media (arteria poplítea)"], [],
 ["La rotura del LCA ocurre en deportistas al cambiar bruscamente de dirección o al aterrizar; son típicos un «pop» y una hinchazón rápida (hemartros).",
  "La rotura del LCP ocurre en las lesiones de salpicadero (rodilla flexionada contra el salpicadero); el cajón posterior es positivo."],
 ["El LCA va del área intercondílea anterior de la tibia a la cara interna del cóndilo lateral; el LCP, del área intercondílea posterior a la cara externa del cóndilo medial.",
  "Los cruzados son intracapsulares pero extrasinoviales."], ["LCA", "LCP", "cruzado"]],
},
"ligg-collateralia-genus": {
"en": ["Collateral ligaments of the knee", "Ligaments supporting the medial and lateral sides of the knee; they prevent the knee opening sideways (valgus/varus).",
 ["Medial femoral epicondyle – medial surface of the tibia; broad and flat, attached to the medial meniscus; resists valgus force",
  "Lateral femoral epicondyle – head of the fibula; a round cord, separate from the meniscus; resists varus force", "Both are taut in full extension"], [],
 ["Blows to the outer side of the knee strain the medial collateral ligament; it is assessed with the valgus stress test."],
 ["The medial collateral ligament is broad and flat and attaches to the medial meniscus; the lateral one is a round cord that does not attach to the meniscus.", "The collateral ligaments are taut in extension and lax in flexion."], ["MCL", "LCL", "collateral ligament"]],
"fr": ["Ligaments collatéraux du genou", "Ligaments qui renforcent les faces médiale et latérale du genou ; ils empêchent son ouverture latérale (valgus/varus).",
 ["Épicondyle médial du fémur – face médiale du tibia ; large et plat, adhérent au ménisque médial ; s'oppose au valgus",
  "Épicondyle latéral du fémur – tête de la fibula ; cordon arrondi, indépendant du ménisque ; s'oppose au varus", "Tous deux sont tendus en extension complète"], [],
 ["Les chocs sur la face latérale du genou sollicitent le ligament collatéral médial ; on l'évalue par le test en valgus forcé."],
 ["Le ligament collatéral médial est large et plat et adhère au ménisque médial ; le latéral est un cordon arrondi qui n'adhère pas au ménisque.", "Les ligaments collatéraux sont tendus en extension et détendus en flexion."], ["LLI", "LLE", "ligament latéral"]],
"de": ["Seitenbänder des Knies", "Bänder, die Innen- und Außenseite des Knies sichern; sie verhindern das seitliche Aufklappen (Valgus/Varus).",
 ["Epicondylus medialis femoris – Innenfläche der Tibia; breit und flach, mit dem Innenmeniskus verwachsen; hemmt Valgusstress",
  "Epicondylus lateralis femoris – Caput fibulae; runder Strang, vom Meniskus getrennt; hemmt Varusstress", "Beide sind in voller Streckung gespannt"], [],
 ["Stöße gegen die Knieaußenseite belasten das Innenband; geprüft wird es mit dem Valgusstresstest."],
 ["Das Innenband ist breit und flach und mit dem Innenmeniskus verwachsen; das Außenband ist ein runder Strang ohne Meniskusverbindung.", "Die Seitenbänder sind in Streckung gespannt und in Beugung locker."], ["Innenband", "Außenband", "Kollateralband"]],
"es": ["Ligamentos colaterales de la rodilla", "Ligamentos que refuerzan los lados medial y lateral de la rodilla; impiden su apertura lateral (valgo/varo).",
 ["Epicóndilo medial del fémur – cara medial de la tibia; ancho y plano, unido al menisco medial; resiste el valgo",
  "Epicóndilo lateral del fémur – cabeza del peroné; cordón redondeado, separado del menisco; resiste el varo", "Ambos están tensos en extensión completa"], [],
 ["Los golpes en la cara lateral de la rodilla fuerzan el ligamento colateral medial; se valora con la prueba de estrés en valgo."],
 ["El colateral medial es ancho y plano y se une al menisco medial; el lateral es un cordón redondeado que no se une al menisco.", "Los colaterales están tensos en extensión y laxos en flexión."], ["LCM", "LCL", "ligamento lateral"]],
},
"artt-tibiofibulares": {
"en": ["Tibiofibular joints", "The upper synovial joint between tibia and fibula, the syndesmosis below and the interosseous membrane of the leg between their shafts.",
 ["Tibiofibular joint: synovial plane joint (head of fibula – lateral tibial condyle)",
  "Tibiofibular syndesmosis: anterior and posterior tibiofibular ligaments; it stabilises the ankle mortise",
  "Gives attachment to the leg muscles and separates the anterior and posterior compartments"], [],
 ["A high ankle sprain is a tear of the syndesmotic ligaments and takes longer to heal."],
 ["The proximal tibiofibular joint is a synovial plane joint, the distal one a syndesmosis.", "In a high ankle sprain (syndesmosis injury) the external rotation test is positive."], []],
"fr": ["Articulations tibio-fibulaires", "L'articulation synoviale supérieure entre tibia et fibula, la syndesmose inférieure et la membrane interosseuse de la jambe entre leurs diaphyses.",
 ["Articulation tibio-fibulaire : synoviale plane (tête de la fibula – condyle latéral du tibia)",
  "Syndesmose tibio-fibulaire : ligaments tibio-fibulaires antérieur et postérieur ; stabilise la mortaise talo-crurale",
  "Donne insertion aux muscles de la jambe et sépare les loges antérieure et postérieure"], [],
 ["L'entorse haute de cheville est une rupture des ligaments de la syndesmose et guérit plus lentement."],
 ["L'articulation tibio-fibulaire proximale est une synoviale plane, la distale une syndesmose.", "Dans l'entorse haute (lésion de la syndesmose), le test en rotation externe est positif."], []],
"de": ["Tibiofibulargelenke", "Das obere Synovialgelenk zwischen Tibia und Fibula, die untere Syndesmose und die Membrana interossea cruris zwischen den Schäften.",
 ["Art. tibiofibularis: synoviales Plangelenk (Caput fibulae – Condylus lateralis tibiae)",
  "Syndesmosis tibiofibularis: Lig. tibiofibulare anterius und posterius; stabilisiert die Malleolengabel",
  "Ursprungsfläche der Unterschenkelmuskeln; trennt vordere und hintere Loge"], [],
 ["Die hohe Sprunggelenkverletzung ist ein Riss der Syndesmosenbänder und heilt langsamer."],
 ["Das proximale Tibiofibulargelenk ist ein synoviales Plangelenk, das distale eine Syndesmose.", "Bei der Syndesmosenverletzung ist der Außenrotationstest positiv."], ["Syndesmose"]],
"es": ["Articulaciones tibioperoneas", "La articulación sinovial superior entre tibia y peroné, la sindesmosis inferior y la membrana interósea de la pierna entre sus diáfisis.",
 ["Articulación tibioperonea: sinovial plana (cabeza del peroné – cóndilo lateral de la tibia)",
  "Sindesmosis tibioperonea: ligamentos tibioperoneos anterior y posterior; estabiliza la mortaja del tobillo",
  "Da inserción a los músculos de la pierna y separa los compartimentos anterior y posterior"], [],
 ["El esguince alto de tobillo es una rotura de los ligamentos de la sindesmosis y tarda más en curar."],
 ["La tibioperonea proximal es una sinovial plana; la distal, una sindesmosis.", "En el esguince alto (lesión de la sindesmosis) la prueba de rotación externa es positiva."], ["sindesmosis"]],
},
"art-talocruralis": {
"en": ["Ankle joint", "The hinge joint between the mortise formed by the lower ends of the tibia and fibula and the trochlea of the talus.",
 ["Synovial hinge joint (ginglymus)", "Lower surface of the tibia and medial malleolus, lateral malleolus – trochlea of the talus",
  "Medial collateral (deltoid) ligament: tibionavicular, tibiocalcaneal, anterior and posterior tibiotalar parts – very strong",
  "Anterior talofibular ligament (the most often torn), calcaneofibular ligament, posterior talofibular ligament",
  "Dorsiflexion (~20°) and plantar flexion (~50°); inversion–eversion occur at the subtalar joint",
  "Most stable in dorsiflexion because the trochlea is wider in front; prone to sprains in plantar flexion"], [],
 ["Most ankle sprains occur in plantar flexion + inversion, and the anterior talofibular ligament tears first.", "The Ottawa rules decide whether an X-ray is needed after an ankle injury.",
  "Pott's fracture: in an eversion injury, a deltoid ligament tear or medial malleolus fracture combined with a fibular fracture."],
 ["The deltoid ligament has four parts (tibionavicular, tibiocalcaneal, anterior and posterior tibiotalar) and limits eversion.", "The Ottawa rules determine the need for X-rays after ankle trauma."], ["ankle"]],
"fr": ["Articulation de la cheville", "Articulation trochléenne entre la mortaise formée par les extrémités inférieures du tibia et de la fibula et la trochlée du talus.",
 ["Articulation synoviale trochléenne (ginglyme)", "Surface inférieure du tibia et malléole médiale, malléole latérale – trochlée du talus",
  "Ligament collatéral médial (deltoïdien) : faisceaux tibio-naviculaire, tibio-calcanéen, tibio-talaires antérieur et postérieur – très solide",
  "Ligament talo-fibulaire antérieur (le plus souvent rompu), ligament calcanéo-fibulaire, ligament talo-fibulaire postérieur",
  "Flexion dorsale (~20°) et flexion plantaire (~50°) ; l'inversion–éversion se fait dans la subtalaire",
  "Plus stable en flexion dorsale car la trochlée est plus large en avant ; exposée aux entorses en flexion plantaire"], [],
 ["La plupart des entorses de cheville surviennent en flexion plantaire + inversion, et le ligament talo-fibulaire antérieur se rompt en premier.", "Les règles d'Ottawa déterminent la nécessité d'une radiographie après un traumatisme de cheville.",
  "Fracture de Pott : lors d'un traumatisme en éversion, rupture du ligament deltoïdien ou fracture de la malléole médiale associée à une fracture de la fibula."],
 ["Le ligament deltoïdien comporte quatre faisceaux (tibio-naviculaire, tibio-calcanéen, tibio-talaires antérieur et postérieur) et limite l'éversion.", "Les règles d'Ottawa déterminent l'indication des radiographies après un traumatisme de cheville."], ["cheville", "talo-crurale"]],
"de": ["Oberes Sprunggelenk", "Scharniergelenk zwischen der von Tibia und Fibula gebildeten Malleolengabel und der Trochlea tali.",
 ["Synoviales Scharniergelenk (Ginglymus)", "Untere Tibiafläche und Malleolus medialis, Malleolus lateralis – Trochlea tali",
  "Lig. collaterale mediale (Lig. deltoideum): Pars tibionavicularis, tibiocalcanea, tibiotalaris anterior und posterior – sehr kräftig",
  "Lig. talofibulare anterius (am häufigsten gerissen), Lig. calcaneofibulare, Lig. talofibulare posterius",
  "Dorsalextension (~20°) und Plantarflexion (~50°); Inversion–Eversion erfolgen im unteren Sprunggelenk",
  "In Dorsalextension am stabilsten, da die Talusrolle vorn breiter ist; in Plantarflexion anfällig für Umknicken"], [],
 ["Die meisten Umknicktraumen erfolgen in Plantarflexion + Inversion, zuerst reißt das Lig. talofibulare anterius.", "Die Ottawa-Regeln entscheiden, ob nach einer Sprunggelenkverletzung geröntgt werden muss.",
  "Pott-Fraktur: bei Eversionsverletzung Riss des Lig. deltoideum oder Innenknöchelfraktur zusammen mit einer Fibulafraktur."],
 ["Das Lig. deltoideum hat vier Teile (tibionavikulär, tibiokalkaneal, vorderer und hinterer tibiotalar) und begrenzt die Eversion.", "Die Ottawa-Regeln bestimmen die Röntgenindikation nach Sprunggelenktrauma."], ["Sprunggelenk", "OSG"]],
"es": ["Articulación del tobillo", "Articulación en bisagra entre la mortaja formada por los extremos inferiores de la tibia y el peroné y la tróclea del astrágalo.",
 ["Articulación sinovial en bisagra (gínglimo)", "Cara inferior de la tibia y maléolo medial, maléolo lateral – tróclea del astrágalo",
  "Ligamento colateral medial (deltoideo): porciones tibionavicular, tibiocalcánea, tibioastragalinas anterior y posterior – muy fuerte",
  "Ligamento peroneoastragalino anterior (el que más se rompe), ligamento peroneocalcáneo, ligamento peroneoastragalino posterior",
  "Flexión dorsal (~20°) y flexión plantar (~50°); la inversión–eversión ocurre en la subastragalina",
  "Más estable en flexión dorsal porque la tróclea es más ancha por delante; propensa a esguinces en flexión plantar"], [],
 ["La mayoría de los esguinces de tobillo se producen en flexión plantar + inversión, y se rompe primero el ligamento peroneoastragalino anterior.", "Las reglas de Ottawa deciden si hace falta radiografía tras una lesión de tobillo.",
  "Fractura de Pott: en una lesión en eversión, rotura del ligamento deltoideo o fractura del maléolo medial junto con fractura del peroné."],
 ["El ligamento deltoideo tiene cuatro porciones (tibionavicular, tibiocalcánea, tibioastragalinas anterior y posterior) y limita la eversión.", "Las reglas de Ottawa determinan la indicación de radiografía tras un traumatismo de tobillo."], ["tobillo"]],
},
"artt-pedis": {
"en": ["Joints of the foot", "The joints between the tarsal bones (subtalar, talocalcaneonavicular, calcaneocuboid), the tarsometatarsal, metatarsophalangeal and interphalangeal joints, and the ligaments supporting the arches of the foot.",
 ["Talus – calcaneus; most inversion and eversion occur here", "Talocalcaneonavicular + calcaneocuboid joints",
  "Tarsal bones and metatarsal bases; the base of the 2nd metatarsal is the keystone",
  "Plantar calcaneonavicular (spring) ligament – supports the head of the talus, long plantar ligament, plantar calcaneocuboid ligament, plantar aponeurosis",
  "Medial and lateral longitudinal arches, transverse arch"], [],
 ["Lisfranc injuries can be missed and lead to chronic pain and deformity.", "Failure of the spring ligament contributes to flat foot (pes planus)."],
 ["Chopart (transverse tarsal) joint: talonavicular + calcaneocuboid; Lisfranc joint: the tarsometatarsal joints.", "The plantar calcaneonavicular (spring) ligament supports the head of the talus; its failure leads to flat foot."], ["subtalar", "Lisfranc", "Chopart"]],
"fr": ["Articulations du pied", "Articulations entre les os du tarse (subtalaire, talo-calcanéo-naviculaire, calcanéo-cuboïdienne), tarso-métatarsiennes, métatarso-phalangiennes et interphalangiennes, et ligaments qui soutiennent les arches du pied.",
 ["Talus – calcanéus ; l'essentiel de l'inversion et de l'éversion s'y fait", "Articulations talo-calcanéo-naviculaire + calcanéo-cuboïdienne",
  "Os du tarse et bases métatarsiennes ; la base du 2e métatarsien en est la clé",
  "Ligament calcanéo-naviculaire plantaire (ligament glénoïdien – soutient la tête du talus), long ligament plantaire, ligament calcanéo-cuboïdien plantaire, aponévrose plantaire",
  "Arches longitudinales médiale et latérale, arche transversale"], [],
 ["Les lésions de Lisfranc peuvent passer inaperçues et laisser douleurs et déformations chroniques.", "L'insuffisance du ligament calcanéo-naviculaire plantaire contribue au pied plat."],
 ["Interligne de Chopart (transverse du tarse) : talo-naviculaire + calcanéo-cuboïdienne ; interligne de Lisfranc : articulations tarso-métatarsiennes.", "Le ligament calcanéo-naviculaire plantaire soutient la tête du talus ; son insuffisance mène au pied plat."], ["subtalaire", "Lisfranc", "Chopart"]],
"de": ["Gelenke des Fußes", "Die Gelenke zwischen den Fußwurzelknochen (unteres Sprunggelenk, Art. talocalcaneonavicularis, calcaneocuboidea), die Tarsometatarsal-, Metatarsophalangeal- und Interphalangealgelenke sowie die Bänder der Fußgewölbe.",
 ["Talus – Calcaneus; hier erfolgt der Großteil von Inversion und Eversion", "Talokalkaneonavikular- + Kalkaneokuboidgelenk",
  "Fußwurzelknochen und Mittelfußbasen; die Basis des 2. Mittelfußknochens ist der Schlussstein",
  "Lig. calcaneonaviculare plantare (Pfannenband – stützt den Taluskopf), Lig. plantare longum, Lig. calcaneocuboideum plantare, Aponeurosis plantaris",
  "Inneres und äußeres Längsgewölbe, Quergewölbe"], [],
 ["Lisfranc-Verletzungen werden leicht übersehen und führen zu chronischen Schmerzen und Fehlstellungen.", "Eine Insuffizienz des Pfannenbands trägt zum Plattfuß (Pes planus) bei."],
 ["Chopart-Gelenk (Art. tarsi transversa): talonavikular + kalkaneokuboidal; Lisfranc-Gelenk: Tarsometatarsalgelenke.", "Das Pfannenband stützt den Taluskopf; seine Insuffizienz führt zum Plattfuß."], ["USG", "Lisfranc", "Chopart"]],
"es": ["Articulaciones del pie", "Las articulaciones entre los huesos del tarso (subastragalina, astragalocalcaneonavicular, calcaneocuboidea), las tarsometatarsianas, metatarsofalángicas e interfalángicas, y los ligamentos que sostienen los arcos del pie.",
 ["Astrágalo – calcáneo; aquí ocurre la mayor parte de la inversión y la eversión", "Articulaciones astragalocalcaneonavicular + calcaneocuboidea",
  "Huesos del tarso y bases de los metatarsianos; la base del 2.º metatarsiano es la clave",
  "Ligamento calcaneonavicular plantar (ligamento en resorte – sostiene la cabeza del astrágalo), ligamento plantar largo, ligamento calcaneocuboideo plantar, aponeurosis plantar",
  "Arcos longitudinales medial y lateral, arco transverso"], [],
 ["Las lesiones de Lisfranc pueden pasar desapercibidas y causar dolor y deformidad crónicos.", "La insuficiencia del ligamento en resorte contribuye al pie plano."],
 ["Articulación de Chopart (transversa del tarso): astragalonavicular + calcaneocuboidea; de Lisfranc: tarsometatarsianas.", "El ligamento calcaneonavicular plantar sostiene la cabeza del astrágalo; su insuficiencia produce pie plano."], ["subastragalina", "Lisfranc", "Chopart"]],
},
}
